import pyomo.environ as pyo

DATA = {
    "assets": ["Stocks", "Bonds", "MutualFunds", "Derivatives"],
    "risk": {
        "Stocks": 3,
        "Bonds": 4,
        "MutualFunds": 2,
        "Derivatives": 5,
    },
    "stocks_bonds_min": 1000,
    "mf_minus_deriv_max": 500,
    "stocks_minus_mf_min": 200,
    "bonds_deriv_eq": 1500,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.ASSETS = pyo.Set(initialize=d["assets"])

    model.invest = pyo.Var(
        model.ASSETS,
        domain=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["risk"][a] * m.invest[a] for a in m.ASSETS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def stocks_bonds_rule(m):
        return m.invest["Stocks"] + m.invest["Bonds"] >= d["stocks_bonds_min"]

    model.stocks_bonds_min = pyo.Constraint(rule=stocks_bonds_rule)

    def mf_deriv_rule(m):
        return m.invest["MutualFunds"] - m.invest["Derivatives"] <= d["mf_minus_deriv_max"]

    model.mf_minus_deriv_max = pyo.Constraint(rule=mf_deriv_rule)

    def stocks_mf_rule(m):
        return m.invest["Stocks"] - m.invest["MutualFunds"] >= d["stocks_minus_mf_min"]

    model.stocks_minus_mf_min = pyo.Constraint(rule=stocks_mf_rule)

    def bonds_deriv_rule(m):
        return m.invest["Bonds"] + m.invest["Derivatives"] == d["bonds_deriv_eq"]

    model.bonds_deriv_eq = pyo.Constraint(rule=bonds_deriv_rule)

    return model

